def heap_queue_largest(nums, n):
    import heapq
    if n <= 0:
        return []
    if not nums:
        return []
    # keep a min-heap of the n largest elements
    heap = []
    for num in nums:
        if len(heap) < n:
            heapq.heappush(heap, num)
        else:
            if num > heap[0]:
                heapq.heapreplace(heap, num)
    # return in descending order
    return sorted(heap, reverse=True)

